/*
 * Conference Map — dependency-free interactive world map (inline SVG).
 *
 * Inputs (defined by _pages/conference-map.md):
 *   window.CONFERENCES  entries of _data/conferences.yml
 *   window.POST_URLS    { "<post file name without .md>": "<url>" }
 *   window.CM_BASEURL   site.baseurl
 *   window.WORLD_MAP    generated by assets/conference-map/world-map-data.js
 */
(function () {
  "use strict";

  var M = window.WORLD_MAP;
  var DATA = window.CONFERENCES || [];
  var POSTS = window.POST_URLS || {};
  var BASE = window.CM_BASEURL || "";
  var root = document.getElementById("conference-map-app");
  if (!root || !M || !DATA.length) return;

  var NS = "http://www.w3.org/2000/svg";
  var W = M.w, H = M.h;
  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------- helpers ---------- */

  function h(tag, attrs, kids) {
    var e = document.createElement(tag);
    set(e, attrs);
    add(e, kids);
    return e;
  }
  function s(tag, attrs, kids) {
    var e = document.createElementNS(NS, tag);
    set(e, attrs);
    add(e, kids);
    return e;
  }
  function set(e, attrs) {
    for (var k in attrs || {}) {
      if (attrs[k] === null || attrs[k] === undefined) continue;
      if (k === "text") e.textContent = attrs[k];
      else e.setAttribute(k, attrs[k]);
    }
  }
  function add(e, kids) {
    (kids || []).forEach(function (c) { if (c) e.appendChild(c); });
  }
  function url(path) {
    return /^(https?:)?\/\//.test(path) ? path : BASE + path;
  }

  /* Equal Earth projection — must match the generator for world-map-data.js */
  var A1 = 1.340264, A2 = -0.081106, A3 = 0.000893, A4 = 0.003796, K = Math.sqrt(3) / 2, RAD = Math.PI / 180;
  function project(lon, lat) {
    var l = lon * RAD, p = lat * RAD, t = Math.asin(K * Math.sin(p)), t2 = t * t, t6 = t2 * t2 * t2;
    var x = l * Math.cos(t) / (K * (A1 + 3 * A2 * t2 + t6 * (7 * A3 + 9 * A4 * t2)));
    var y = -t * (A1 + A2 * t2 + t6 * (A3 + A4 * t2));
    return [x * M.scale + M.tx, y * M.scale + M.ty];
  }

  var MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
  function sortKey(c) {
    var m = MONTHS.indexOf(String(c.date || "").slice(0, 3).toLowerCase());
    return (c.year || 0) * 100 + (m < 0 ? 0 : m + 1);
  }

  /* ---------- data: group entries that share a location ---------- */

  var places = [], byKey = {}, byId = {};
  DATA.forEach(function (c, i) {
    c._i = i;
    var key = Number(c.lat).toFixed(3) + "," + Number(c.lon).toFixed(3);
    var p = byKey[key];
    if (!p) {
      var xy = project(Number(c.lon), Number(c.lat));
      p = byKey[key] = { key: key, city: c.city, country: c.country, x: xy[0], y: xy[1], items: [] };
      places.push(p);
    }
    c._place = p;
    p.items.push(c);
    byId[c.id] = c;
  });
  places.forEach(function (p) {
    p.items.sort(function (a, b) { return sortKey(b) - sortKey(a) || b._i - a._i; });
  });
  var chronological = DATA.slice().sort(function (a, b) { return sortKey(b) - sortKey(a) || b._i - a._i; });

  /* ---------- DOM skeleton ---------- */

  var countries = {}, cities = {};
  DATA.forEach(function (c) { countries[c.country] = 1; cities[c.city] = 1; });

  var stats = h("p", { class: "cm-stats" }, [
    h("span", { text: DATA.length + (DATA.length === 1 ? " event" : " events") }),
    h("span", { text: Object.keys(cities).length + (Object.keys(cities).length === 1 ? " city" : " cities") }),
    h("span", { text: Object.keys(countries).length + (Object.keys(countries).length === 1 ? " country" : " countries") })
  ]);

  var svg = s("svg", { class: "cm-svg", viewBox: "0 0 " + W + " " + H, role: "group", "aria-label": "World map of conferences" });
  var gGrat = s("g", { class: "cm-graticule" });
  var gLand = s("g", {}, [
    s("path", { class: "cm-land", d: M.land }),
    s("path", { class: "cm-borders", d: M.borders, "vector-effect": "non-scaling-stroke" })
  ]);
  var gPins = s("g", { class: "cm-pins" });
  svg.appendChild(s("rect", { class: "cm-ocean", x: -5000, y: -5000, width: 12000, height: 12000 }));
  svg.appendChild(gGrat);
  svg.appendChild(gLand);
  svg.appendChild(gPins);

  // graticule every 30 degrees
  (function () {
    var d = "", lat, lon, i, pt;
    for (lat = -30; lat <= 60; lat += 30) {
      pt = project(-180, lat); d += "M" + pt[0].toFixed(1) + " " + pt[1].toFixed(1);
      pt = project(180, lat); d += "L" + pt[0].toFixed(1) + " " + pt[1].toFixed(1);
    }
    for (lon = -150; lon <= 150; lon += 30) {
      for (i = 0, lat = -57; lat <= 84; lat += 3, i++) {
        pt = project(lon, lat);
        d += (i === 0 ? "M" : "L") + pt[0].toFixed(1) + " " + pt[1].toFixed(1);
      }
    }
    gGrat.appendChild(s("path", { d: d, "vector-effect": "non-scaling-stroke" }));
  })();

  var resetBtn = h("button", { class: "cm-reset", type: "button", "aria-label": "Show the whole world", text: "World view" });
  var card = h("aside", { class: "cm-card", "aria-live": "polite", hidden: "" });
  var stage = h("div", { class: "cm-stage" }, [svg, resetBtn, card]);
  var list = h("div", { class: "cm-list" });

  root.textContent = "";
  root.appendChild(stats);
  root.appendChild(stage);
  root.appendChild(list);

  /* ---------- pins ---------- */

  places.forEach(function (p) {
    p.hit = s("circle", { class: "cm-hit", cx: p.x, cy: p.y });
    p.ring = s("circle", { class: "cm-ring", cx: p.x, cy: p.y });
    p.dot = s("circle", { class: "cm-dot", cx: p.x, cy: p.y });
    p.label = s("text", { class: "cm-label", text: p.city + (p.items.length > 1 ? " · " + p.items.length : "") });
    p.g = s("g", {
      class: "cm-pin", tabindex: "0", role: "button",
      "aria-label": p.city + ", " + p.country + ": " + p.items.map(function (c) { return c.name; }).join(", ")
    }, [p.ring, p.hit, p.dot, p.label]);
    p.g.addEventListener("click", function (e) { e.stopPropagation(); selectPlace(p); });
    p.g.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); selectPlace(p); }
    });
    gPins.appendChild(p.g);
  });

  /* ---------- view (zoom) ---------- */

  var view = { x: 0, y: 0, w: W, h: H };
  var anim = null;

  function applyView() {
    svg.setAttribute("viewBox", view.x.toFixed(2) + " " + view.y.toFixed(2) + " " + view.w.toFixed(2) + " " + view.h.toFixed(2));
    layoutPins();
  }

  function layoutPins() {
    var k = (svg.clientWidth || 1000) / view.w; // screen px per viewBox unit
    var placed = [];
    var order = places.slice().sort(function (a, b) {
      return (b === current) - (a === current) || b.items.length - a.items.length || a.items[0]._i - b.items[0]._i;
    });
    order.forEach(function (p) {
      var r = (p.items.length > 1 ? 5.5 : 4.5) / k;
      p.dot.setAttribute("r", r);
      p.ring.setAttribute("r", r);
      p.hit.setAttribute("r", 18 / k);

      var fs = 11 / k, charW = fs * 0.58;
      var w = p.label.textContent.length * charW, hh = fs * 1.2;
      var right = p.x + r + 4 / k + w < view.x + view.w - 6 / k;
      var x0 = right ? p.x + r + 4 / k : p.x - r - 4 / k - w;
      var box = { x: x0, y: p.y - hh / 2, w: w, h: hh };
      var clash = placed.some(function (b) {
        return box.x < b.x + b.w && box.x + box.w > b.x && box.y < b.y + b.h && box.y + box.h > b.y;
      });
      // keep the dot itself in the collision set
      placed.push({ x: p.x - r, y: p.y - r, w: 2 * r, h: 2 * r });
      if (clash && p !== current) {
        p.label.setAttribute("visibility", "hidden");
      } else {
        p.label.removeAttribute("visibility");
        p.label.setAttribute("x", right ? p.x + r + 4 / k : p.x - r - 4 / k);
        p.label.setAttribute("y", p.y + fs * 0.35);
        p.label.setAttribute("text-anchor", right ? "start" : "end");
        p.label.setAttribute("font-size", fs);
        placed.push(box);
      }
    });
  }

  function animateTo(target) {
    if (anim) cancelAnimationFrame(anim);
    var from = { x: view.x, y: view.y, w: view.w, h: view.h };
    if (reduceMotion) { view = target; applyView(); return; }
    var t0 = null, dur = 650;
    function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
    function step(ts) {
      if (t0 === null) t0 = ts;
      var t = Math.min(1, (ts - t0) / dur), e = ease(t);
      view = {
        x: from.x + (target.x - from.x) * e,
        y: from.y + (target.y - from.y) * e,
        w: from.w + (target.w - from.w) * e,
        h: from.h + (target.h - from.h) * e
      };
      applyView();
      if (t < 1) anim = requestAnimationFrame(step); else anim = null;
    }
    anim = requestAnimationFrame(step);
  }

  function isWide() { return stage.clientWidth >= 900; }

  function zoomTo(p) {
    var z = 3.2, w = W / z, hgt = H / z;
    var fx = isWide() ? 0.3 : 0.5; // leave room for the side card on wide screens
    var x = p.x - w * fx, y = p.y - hgt * 0.5;
    x = Math.max(0, Math.min(W - w, x));
    y = Math.max(0, Math.min(H - hgt, y));
    animateTo({ x: x, y: y, w: w, h: hgt });
    resetBtn.classList.add("is-visible");
  }

  function zoomOut() {
    animateTo({ x: 0, y: 0, w: W, h: H });
    resetBtn.classList.remove("is-visible");
  }

  /* ---------- card ---------- */

  var current = null;      // selected place
  var currentItem = null;  // selected conference

  function renderCard(p, item) {
    card.textContent = "";

    var close = h("button", { class: "cm-close", type: "button", "aria-label": "Close", text: "×" });
    close.addEventListener("click", clearSelection);
    card.appendChild(close);

    if (p.items.length > 1) {
      var tabs = h("div", { class: "cm-tabs", role: "tablist" });
      p.items.forEach(function (c) {
        var tab = h("button", {
          class: "cm-tab" + (c === item ? " is-active" : ""), type: "button", role: "tab",
          "aria-selected": c === item ? "true" : "false", text: c.name
        });
        tab.addEventListener("click", function () { selectItem(c); });
        tabs.appendChild(tab);
      });
      card.appendChild(tabs);
    }

    var head = h("header", { class: "cm-card-head" }, [
      h("p", { class: "cm-kicker", text: item.date || String(item.year) }),
      h("h2", { text: item.name }),
      h("p", { class: "cm-place", text: item.city + ", " + item.country })
    ]);
    card.appendChild(head);

    if (item.title) card.appendChild(h("p", { class: "cm-title", text: item.title }));
    if (item.summary) card.appendChild(h("p", { class: "cm-summary", text: item.summary }));

    if (item.photos && item.photos.length) {
      var grid = h("div", { class: "cm-photos cm-photos-" + Math.min(item.photos.length, 3) });
      item.photos.forEach(function (ph) {
        var img = h("img", { src: url(ph.src), alt: ph.alt || item.name, loading: "lazy" });
        var fig = h("figure", { class: "cm-photo" }, [
          h("button", { class: "cm-photo-btn", type: "button", "aria-label": "Enlarge: " + (ph.caption || ph.alt || item.name) }, [img]),
          ph.caption ? h("figcaption", { text: ph.caption }) : null
        ]);
        img.addEventListener("error", function () { fig.style.display = "none"; });
        fig.querySelector("button").addEventListener("click", function () { openLightbox(ph, item); });
        grid.appendChild(fig);
      });
      card.appendChild(grid);
    }

    var href = item.post ? POSTS[item.post] : null;
    if (href) {
      card.appendChild(h("a", { class: "cm-post", href: href, text: "Read the conference post →" }));
    }
    card.removeAttribute("hidden");
    card.scrollTop = 0;
    requestAnimationFrame(function () { card.classList.add("is-visible"); });
  }

  function markActive() {
    places.forEach(function (p) { p.g.classList.toggle("is-active", p === current); });
    Array.prototype.forEach.call(list.querySelectorAll(".cm-row"), function (b) {
      b.classList.toggle("is-active", !!currentItem && b.getAttribute("data-id") === currentItem.id);
    });
  }

  function selectItem(item, opts) {
    opts = opts || {};
    var p = item._place, changed = p !== current;
    current = p;
    currentItem = item;
    renderCard(p, item);
    markActive();
    if (changed || opts.zoom) zoomTo(p); else layoutPins();
    try { history.replaceState(null, "", "#" + item.id); } catch (e) { /* ignore */ }
    if (opts.scroll && !isWide()) {
      card.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "nearest" });
    }
  }

  function selectPlace(p) {
    selectItem(p.items[0], { scroll: true });
  }

  function clearSelection() {
    current = null;
    currentItem = null;
    card.classList.remove("is-visible");
    card.setAttribute("hidden", "");
    markActive();
    zoomOut();
    try { history.replaceState(null, "", location.pathname + location.search); } catch (e) { /* ignore */ }
  }

  svg.addEventListener("click", function () { if (current) clearSelection(); });
  resetBtn.addEventListener("click", function () { if (current) clearSelection(); else zoomOut(); });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      if (lightbox.classList.contains("is-open")) closeLightbox();
      else if (current) clearSelection();
    }
  });

  /* ---------- timeline list ---------- */

  (function () {
    var year = null, group = null;
    chronological.forEach(function (c) {
      if (c.year !== year) {
        year = c.year;
        group = h("section", { class: "cm-year" }, [h("h3", { text: String(year) })]);
        list.appendChild(group);
      }
      var row = h("button", { class: "cm-row", type: "button", "data-id": c.id }, [
        h("span", { class: "cm-row-name", text: c.name }),
        h("span", { class: "cm-row-meta", text: c.city + ", " + c.country + (c.date ? " · " + c.date : "") })
      ]);
      row.addEventListener("click", function () {
        selectItem(c, { zoom: true, scroll: true });
        stage.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "start" });
      });
      group.appendChild(row);
    });
  })();

  /* ---------- lightbox ---------- */

  var lbImg = h("img", { alt: "" });
  var lbCap = h("p", { class: "cm-lb-cap" });
  var lightbox = h("div", { class: "cm-lightbox", role: "dialog", "aria-modal": "true", "aria-label": "Photo" }, [
    h("button", { class: "cm-lb-close", type: "button", "aria-label": "Close", text: "×" }),
    lbImg, lbCap
  ]);
  lightbox.addEventListener("click", closeLightbox);
  document.body.appendChild(lightbox);

  function openLightbox(ph, item) {
    lbImg.src = url(ph.src);
    lbImg.alt = ph.alt || item.name;
    lbCap.textContent = (ph.caption || "") + (ph.caption ? " — " : "") + item.name + ", " + item.city + " " + item.year;
    lightbox.classList.add("is-open");
  }
  function closeLightbox() {
    lightbox.classList.remove("is-open");
    lbImg.removeAttribute("src");
  }

  /* ---------- init ---------- */

  applyView();
  window.addEventListener("resize", layoutPins);

  var hashId = decodeURIComponent((location.hash || "").slice(1));
  if (hashId && byId[hashId]) selectItem(byId[hashId], { zoom: true });
  window.addEventListener("hashchange", function () {
    var id = decodeURIComponent((location.hash || "").slice(1));
    if (id && byId[id] && byId[id] !== currentItem) selectItem(byId[id], { zoom: true });
  });
})();
